#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // The original binary expects exactly two arguments: a shift value and a text string.
    // If the number of arguments is insufficient, or the text is too long (>1024),
    // it prints a simple usage message.
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *shift_str = argv[1];
    const char *text = argv[2];

    // The original program limits the input string to 1024 characters.
    if (strlen(text) > 1024) {
        puts("USAGE");
        return 0;
    }

    // Convert shift to a signed long, handling optional leading '+' or '-'.
    long shift_val = strtol(shift_str, NULL, 10);

    // Normalise the shift to the range [0,25] (the original code performed a
    // division‑by‑26 using magic numbers and then added 26 if the result was
    // negative).  This reproduces the same behaviour for positive, zero and
    // negative shifts.
    int shift = (int)shift_val;
    shift = ((shift % 26) + 26) % 26; // ensure non‑negative remainder

    // Perform the Caesar cipher, preserving case and leaving non‑alphabetic
    // characters unchanged.
    for (size_t i = 0; text[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + shift) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + shift) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
